import { registerMvuSchema } from 'https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource/dist/util/mvu_zod.js';

export const Schema = z.object({
  世界: z.object({
    当前日期: z.string(),
    当前时间: z.string()
  }),

  周语晴: z.object({
    背德值: z.coerce.number().transform(v => _.clamp(v, 0, 200)),
    是否怀孕: z.boolean(),
    当前衣着: z.string(),
    双乳状态: z.string(),
    阴道状态: z.string(),
    子宫内部状态: z.string(),
    后穴状态: z.string(),
    足部状态: z.string(),
    内心独白: z.string()
  }),

  马俊伟: z.object({
    欲望值: z.coerce.number().transform(v => _.clamp(v, 0, 200))
  }),

  事件: z.object({
    厨房的温情: z.boolean(),
    夜晚的准备: z.boolean(),
    井边的协作: z.boolean(),
    贴心的照顾: z.boolean(),
    田间的意外: z.boolean(),
    餐桌上的默契: z.boolean(),
    深夜的关怀: z.boolean(),
    一件心意: z.boolean(),
    主动的亲近: z.boolean(),
    家的新定义: z.boolean(),
    午夜的期待: z.boolean(),
    角色的重新定位: z.boolean(),
    体贴的安排: z.boolean(),
    默契的配合: z.boolean(),
    细致的观察: z.boolean(),
    暗示的艺术: z.boolean(),
    角色的确认: z.boolean(),
    心理的转变: z.boolean(),
    主动的退让: z.boolean(),
    完美的平衡: z.boolean()
  })
});

$(() => {
  registerMvuSchema(Schema);
})
